@Service
public class PaymentService {

    private final PaymentRepository paymentRepository;
    private final IdempotencyStore idempotencyStore;

    public PaymentService(PaymentRepository paymentRepository, IdempotencyStore idempotencyStore) {
        this.paymentRepository = paymentRepository;
        this.idempotencyStore = idempotencyStore;
    }

    @Transactional
    public PaymentResponse processPayment(String idempotencyKey, PaymentRequest request) {
        // Check if the key already exists in the cache or database
        Optional<PaymentResponse> cachedResponse = idempotencyStore.get(idempotencyKey);
        if (cachedResponse.isPresent()) {
            return cachedResponse.get();
        }

        // Acquire lock or rely on unique constraint to prevent race conditions
        try {
            idempotencyStore.markAsPending(idempotencyKey);

            // Execute core business logic
            Payment payment = paymentRepository.save(new Payment(request));
            PaymentResponse response = new PaymentResponse(payment.getId(), "SUCCESS");

            // Cache the final response alongside the key
            idempotencyStore.saveResult(idempotencyKey, response);
            return response;

        } catch (DataIntegrityViolationException e) {
            // Concurrent request beat us to it; fetch and return the original result
            return idempotencyStore.awaitResult(idempotencyKey);
        }
    }
}
